<?php
/** Read-only LiteSpeed capability and Guest Vary diagnostics. @package NakhostinPerformanceEngine */
namespace Nakhostin\PerformanceEngine\Integrations\LiteSpeed;
final class LiteSpeedHealthCheck {
	/** @var LiteSpeedDetector */ private $detector; public function __construct( LiteSpeedDetector $detector ) { $this->detector = $detector; }
	public function run( ?array $guest_vary_response = null, array $response_headers = array(), string $owner = 'unknown' ): array { $detected = $this->detector->detect(); $guest = array( 'status' => 'not_tested', 'http_status' => null, 'likely_layer' => null, 'npe_action' => 'none' ); if ( null !== $guest_vary_response ) { $status = (int) ( $guest_vary_response['status'] ?? 0 ); $body = (string) ( $guest_vary_response['body'] ?? '' ); $json = json_decode( $body, true ); $failed = 200 !== $status || ! is_array( $json ); $guest = array( 'status' => $failed ? 'failed' : 'healthy', 'http_status' => $status, 'likely_layer' => $failed ? 'web_server_waf_modsecurity_or_litespeed_configuration' : null, 'npe_action' => $failed ? 'external_configuration_required' : 'none' ); } return array( 'plugin_active' => $detected['active'] ?? false, 'server_detected' => $detected['server'] ?? false, 'page_cache_available' => $detected['cache_capable'] ?? false, 'cache_owner' => $owner, 'purge_api_available' => has_action( 'litespeed_purge_all' ) || has_action( 'litespeed_purge_url' ), 'guest_mode_detectable' => defined( 'LSCWP_V' ), 'guest_vary' => $guest, 'cache_header' => (string) ( $response_headers['x-litespeed-cache'] ?? $response_headers['X-LiteSpeed-Cache'] ?? '' ) ); }
}
